import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";

type Status = "open" | "done";

interface Task {
  id: number;
  title: string;
  status: Status;
  createdAt: string;
  tags: string[];
  due?: string;
  completedAt?: string;
}

interface Database {
  nextId: number;
  tasks: Task[];
}

type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue | undefined };

class CliError extends Error {}

const databasePath = resolve(process.env.TASKBOARD_FILE || ".taskboard.json");

function fail(message: string): never {
  throw new CliError(message);
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const candidate = new Date(Date.UTC(year, month - 1, day));
  return candidate.getUTCFullYear() === year && candidate.getUTCMonth() === month - 1 && candidate.getUTCDate() === day;
}

function requireDate(value: string, label: string): string {
  if (!isDate(value)) fail(`${label} must be a valid date in YYYY-MM-DD format`);
  return value;
}

function validateTask(value: unknown): value is Task {
  if (!isPlainObject(value)) return false;
  const allowed = new Set(["id", "title", "status", "createdAt", "tags", "due", "completedAt"]);
  if (Object.keys(value).some((key) => !allowed.has(key))) return false;
  if (!Number.isSafeInteger(value.id) || (value.id as number) < 1) return false;
  if (typeof value.title !== "string" || value.title.trim() === "") return false;
  if (value.status !== "open" && value.status !== "done") return false;
  if (typeof value.createdAt !== "string" || Number.isNaN(Date.parse(value.createdAt))) return false;
  if (!Array.isArray(value.tags) || value.tags.some((tag) => typeof tag !== "string" || tag === "" || tag !== tag.trim().toLowerCase())) return false;
  if (new Set(value.tags).size !== value.tags.length) return false;
  if (value.due !== undefined && !isDate(value.due)) return false;
  if (value.status === "done") {
    if (typeof value.completedAt !== "string" || Number.isNaN(Date.parse(value.completedAt))) return false;
  } else if (value.completedAt !== undefined) {
    return false;
  }
  return true;
}

function validateDatabase(value: unknown): value is Database {
  if (!isPlainObject(value) || Object.keys(value).some((key) => key !== "nextId" && key !== "tasks")) return false;
  if (!Number.isSafeInteger(value.nextId) || (value.nextId as number) < 1 || !Array.isArray(value.tasks)) return false;
  if (!value.tasks.every(validateTask)) return false;
  const ids = value.tasks.map((task) => task.id);
  return new Set(ids).size === ids.length && ids.every((id) => id < (value.nextId as number));
}

async function loadDatabase(): Promise<Database> {
  let raw: string;
  try {
    raw = await readFile(databasePath, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return { nextId: 1, tasks: [] };
    throw error;
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    fail(`database is malformed: ${databasePath}`);
  }
  if (!validateDatabase(parsed)) fail(`database has an invalid structure: ${databasePath}`);
  return parsed;
}

async function saveDatabase(database: Database): Promise<void> {
  const parent = dirname(databasePath);
  await mkdir(parent, { recursive: true });
  const temporaryPath = `${databasePath}.tmp-${process.pid}-${crypto.randomUUID()}`;
  try {
    await writeFile(temporaryPath, `${JSON.stringify(database, null, 2)}\n`, { encoding: "utf8", flag: "wx" });
    await rename(temporaryPath, databasePath);
  } catch (error) {
    await unlink(temporaryPath).catch(() => undefined);
    throw error;
  }
}

function parseFlags(args: string[], allowed: ReadonlySet<string>): Map<string, string> {
  const flags = new Map<string, string>();
  for (let index = 0; index < args.length; index += 2) {
    const flag = args[index];
    if (!flag?.startsWith("--")) fail(`unexpected argument: ${flag ?? ""}`);
    if (!allowed.has(flag)) fail(`unknown flag: ${flag}`);
    if (flags.has(flag)) fail(`duplicate flag: ${flag}`);
    const value = args[index + 1];
    if (value === undefined || value.startsWith("--")) fail(`missing value for ${flag}`);
    flags.set(flag, value);
  }
  return flags;
}

function normalizeTag(tag: string): string {
  const normalized = tag.trim().toLowerCase();
  if (!normalized) fail("tags must not be empty");
  return normalized;
}

function parseTags(raw: string | undefined): string[] {
  if (raw === undefined) return [];
  const tags = raw.split(",").map(normalizeTag);
  return [...new Set(tags)];
}

function parseId(raw: string | undefined): number {
  if (raw === undefined || !/^[1-9]\d*$/.test(raw)) fail("ID must be a positive integer");
  const id = Number(raw);
  if (!Number.isSafeInteger(id)) fail("ID must be a safe positive integer");
  return id;
}

function findTask(database: Database, id: number): Task {
  const task = database.tasks.find((candidate) => candidate.id === id);
  if (!task) fail(`task ${id} not found`);
  return task;
}

async function add(args: string[]): Promise<Task> {
  const flags = parseFlags(args, new Set(["--title", "--tags", "--due"]));
  const title = flags.get("--title")?.trim();
  if (!title) fail("--title is required and must not be empty");
  const dueValue = flags.get("--due");
  const database = await loadDatabase();
  const task: Task = {
    id: database.nextId,
    title,
    status: "open",
    createdAt: new Date().toISOString(),
    tags: parseTags(flags.get("--tags")),
    ...(dueValue === undefined ? {} : { due: requireDate(dueValue, "--due") }),
  };
  database.nextId += 1;
  database.tasks.push(task);
  await saveDatabase(database);
  return task;
}

async function list(args: string[]): Promise<Task[]> {
  const flags = parseFlags(args, new Set(["--status", "--tag", "--overdue"]));
  const status = flags.get("--status");
  if (status !== undefined && status !== "open" && status !== "done") fail("--status must be open or done");
  const tag = flags.has("--tag") ? normalizeTag(flags.get("--tag")!) : undefined;
  const overdue = flags.has("--overdue") ? requireDate(flags.get("--overdue")!, "--overdue") : undefined;
  const database = await loadDatabase();
  return database.tasks
    .filter((task) => status === undefined || task.status === status)
    .filter((task) => tag === undefined || task.tags.includes(tag))
    .filter((task) => overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
    .sort((left, right) => left.id - right.id);
}

async function done(args: string[]): Promise<Task> {
  if (args.length !== 1) fail("usage: done ID");
  const database = await loadDatabase();
  const task = findTask(database, parseId(args[0]));
  if (task.status === "open") {
    task.status = "done";
    task.completedAt = new Date().toISOString();
    await saveDatabase(database);
  }
  return task;
}

async function deleteTask(args: string[]): Promise<Task> {
  if (args.length !== 1) fail("usage: delete ID");
  const database = await loadDatabase();
  const task = findTask(database, parseId(args[0]));
  database.tasks = database.tasks.filter((candidate) => candidate.id !== task.id);
  await saveDatabase(database);
  return task;
